\llbracket A\land B\rrbracket_{\mathcal E}^{700}
=
\llbracket A\rrbracket_{\mathcal E}^{700}\cap\llbracket B\rrbracket_{\mathcal E}^{700},

b\in\llbracket \exists x\bullet A\rrbracket_{\mathcal E}^{700}
\Longleftrightarrow
\exists a\in\mathsf{Val}_{700}\ b[x:=a]\in\llbracket A\rrbracket_{\mathcal E}^{700}.

b\in\llbracket A[x\mapsto y]\rrbracket_{\mathcal E}^{700}
\Longleftrightarrow
b[x:=b(y)]\in\llbracket A\rrbracket_{\mathcal E}^{700}
